enum Shape { Circle { r: f64 }, Rect { w: f64, h: f64 }, Unit }

fn area(s: &Shape) -> f64 {
    match s {                        // E0004 if an arm is missing
        Shape::Circle { r } => std::f64::consts::PI * r * r,
        Shape::Rect { w, h } => w * h,
        Shape::Unit => 1.0,
    }
}
